import React, { useState, useEffect, useRef } from 'react';
import './EventTable.css';

const EventTable = ({ events, loading, totalEvents, currentPage, pageSize, onPageChange }) => {
  const [sortedEvents, setSortedEvents] = useState([]);
  const [sortConfig, setSortConfig] = useState({ key: null, direction: 'asc' });
  const [filters, setFilters] = useState({});
  const [openFilterId, setOpenFilterId] = useState(null);
  const filterRefs = useRef({});

  // Apply sorting and filtering when events change
  useEffect(() => {
    let filteredData = [...events];

    // Apply filters
    Object.keys(filters).forEach(key => {
      if (filters[key] && filters[key].length > 0) {
        filteredData = filteredData.filter(item => {
          const value = getValueByKey(item, key);
          return filters[key].includes(value);
        });
      }
    });

    // Apply sorting
    if (sortConfig.key) {
      filteredData.sort((a, b) => {
        const aValue = getValueByKey(a, sortConfig.key);
        const bValue = getValueByKey(b, sortConfig.key);

        if (aValue < bValue) {
          return sortConfig.direction === 'asc' ? -1 : 1;
        }
        if (aValue > bValue) {
          return sortConfig.direction === 'asc' ? 1 : -1;
        }
        return 0;
      });
    }

    setSortedEvents(filteredData);
  }, [events, sortConfig, filters]);

  // Close filter dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (openFilterId && filterRefs.current[openFilterId] && !filterRefs.current[openFilterId].contains(event.target)) {
        setOpenFilterId(null);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [openFilterId]);

  // Get value for sorting/filtering based on key
  const getValueByKey = (item, key) => {
    switch(key) {
      case 'report_id':
        return item.top_safetyreportid;
      case 'report_date':
        return item.top_receivedate;
      case 'country':
        return item.top_occurcountry || 'Unknown';
      case 'medication':
        return getDrugName(item.drug_medicinalproduct);
      case 'adverse_event':
        return item.reaction_reactionmeddrapt;
      case 'severity':
        return getSeverityText(item.top_serious);
      case 'gender':
        return getGenderText(item.patient_patientsex);
      case 'age':
        return item.patient_patientonsetage != null ? parseInt(item.patient_patientonsetage, 10) : -1;
      case 'weight':
        return item.patient_patientweight != null ? item.patient_patientweight : -1;
      case 'route':
        return formatRoute(item.drug_openfda_route);
      case 'start_date':
        return item.drug_drugstartdate || '';
      case 'end_date':
        return item.drug_drugenddate || '';
      case 'dosage':
        return getDosage(item.drug_drugstructuredosagenumb, item.drug_drugstructuredosageunit);
      default:
        return '';
    }
  };

  // Handle sorting when clicking a column header
  const handleSort = (key) => {
    let direction = 'asc';
    if (sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  // Handle filter toggle
  const toggleFilter = (id) => {
    setOpenFilterId(openFilterId === id ? null : id);
  };

  // Handle filter selection
  const handleFilterChange = (key, value) => {
    setFilters(prevFilters => {
      const newFilters = { ...prevFilters };
      if (!newFilters[key]) {
        newFilters[key] = [];
      }

      if (newFilters[key].includes(value)) {
        newFilters[key] = newFilters[key].filter(v => v !== value);
      } else {
        newFilters[key] = [...newFilters[key], value];
      }

      if (newFilters[key].length === 0) {
        delete newFilters[key];
      }

      return newFilters;
    });
  };

  // Filter search input
  const [filterSearch, setFilterSearch] = useState('');

  // Generate unique filter options for a column
  const getFilterOptions = (key) => {
    const options = new Set();
    events.forEach(event => {
      const value = getValueByKey(event, key);
      if (value !== undefined && value !== null) {
        options.add(value);
      }
    });
    return Array.from(options).sort();
  };

  // Reset all filters
  const resetAllFilters = () => {
    setFilters({});
    setFilterSearch('');
  };

  // Format date from YYYYMMDD to YYYY-MM-DD for display
  const formatDate = (dateStr) => {
    if (!dateStr || dateStr.length !== 8) return 'Unknown';
    return `${dateStr.substring(0, 4)}-${dateStr.substring(4, 6)}-${dateStr.substring(6, 8)}`;
  };

  // Get severity text based on serious flag
  const getSeverityText = (serious) => {
    return serious === 1 ? 'Serious' : 'Non-serious';
  };

  // Get patient gender text
  const getGenderText = (genderCode) => {
    switch (genderCode) {
      case 1: return 'Male';
      case 2: return 'Female';
      default: return 'Unknown';
    }
  };

  // Calculate total number of pages
  const totalPages = Math.ceil(totalEvents / pageSize);

  // Generate array of page numbers to display
  const getPageNumbers = () => {
    const maxPagesToShow = 5;
    let startPage = Math.max(1, currentPage - Math.floor(maxPagesToShow / 2));
    let endPage = startPage + maxPagesToShow - 1;

    if (endPage > totalPages) {
      endPage = totalPages;
      startPage = Math.max(1, endPage - maxPagesToShow + 1);
    }

    return Array.from({ length: endPage - startPage + 1 }, (_, i) => startPage + i);
  };

  // 药物名标准化显示
  const getDrugName = (name) => {
    if (!name) return '';
    const n = name.toLowerCase();
    if (n === 'semaglutide') return 'Semaglutide';
    if (n === 'tirzepatide') return 'Tirzepatide';
    return name.charAt(0).toUpperCase() + name.slice(1).toLowerCase();
  };

  // 剂量单位代码映射
  const dosageUnitMap = {
    '001': 'mg',
    '002': 'g',
    '003': 'ml',
    '004': 'units',
    '005': 'ug',
    '006': 'ng',
    '007': 'meq',
    '008': 'mmol',
    '009': '%',
    '010': 'IU'
  };
  const getDosage = (num, unit) => {
    if (!num) return 'Unknown';
    if (unit && dosageUnitMap[unit]) return `${num} ${dosageUnitMap[unit]}`;
    if (unit) return `${num} ${unit}`;
    return num;
  };

  const formatRoute = (route) => {
    if (!route) return 'Unknown';
    return route.charAt(0).toUpperCase() + route.slice(1).toLowerCase();
  };

  // Render the filter dropdown
  const renderFilterDropdown = (key, title) => {
    const options = getFilterOptions(key);
    const filteredOptions = filterSearch 
      ? options.filter(opt => String(opt).toLowerCase().includes(filterSearch.toLowerCase()))
      : options;

    return (
      <div className="filter-dropdown" ref={el => filterRefs.current[key] = el}>
        <div className="filter-header">
          <input 
            type="text" 
            placeholder="Search..." 
            value={filterSearch}
            onChange={(e) => setFilterSearch(e.target.value)}
            onClick={(e) => e.stopPropagation()}
            className="filter-search"
          />
        </div>
        <div className="filter-options">
          {filteredOptions.length > 0 ? (
            filteredOptions.map((option, index) => (
              <label key={index} className="filter-option">
                <input
                  type="checkbox"
                  checked={filters[key]?.includes(option) || false}
                  onChange={() => handleFilterChange(key, option)}
                  onClick={(e) => e.stopPropagation()}
                />
                <span>{option}</span>
              </label>
            ))
          ) : (
            <div className="no-options">No options found</div>
          )}
        </div>
        <div className="filter-footer">
          <button onClick={(e) => {
            e.stopPropagation();
            const newFilters = {...filters};
            delete newFilters[key];
            setFilters(newFilters);
            setFilterSearch('');
          }}>Clear</button>
        </div>
      </div>
    );
  };

  // Render table header with sort and filter
  const renderTableHeader = (key, title) => {
    const isSorted = sortConfig.key === key;
    const sortDirection = isSorted ? sortConfig.direction : null;
    const isFiltered = filters[key] && filters[key].length > 0;

    return (
      <th>
        <div className="table-header">
          <div className="header-content" onClick={() => handleSort(key)}>
            {title}
            {isSorted && (
              <span className={`sort-icon ${sortDirection === 'asc' ? 'asc' : 'desc'}`}>
                {sortDirection === 'asc' ? '▲' : '▼'}
              </span>
            )}
          </div>
          <div className="filter-icon" onClick={() => toggleFilter(key)}>
            <span className={isFiltered ? 'active' : ''}>🔍</span>
            {openFilterId === key && renderFilterDropdown(key, title)}
          </div>
        </div>
      </th>
    );
  };

  return (
    <div className="event-table-container">
      {loading ? (
        <div className="loading-indicator">Loading data...</div>
      ) : sortedEvents.length === 0 ? (
        <div className="no-data-message">
          {Object.keys(filters).length > 0 ? (
            <>
              No data matches your filters. 
              <button className="reset-filters-btn" onClick={resetAllFilters}>Reset Filters</button>
            </>
          ) : (
            "No adverse events found. Try adjusting your filters."
          )}
        </div>
      ) : (
        <>
          <div className="table-responsive">
            <table className="event-table">
              <thead>
                <tr>
                  {renderTableHeader('report_id', 'Report ID')}
                  {renderTableHeader('report_date', 'Report Date')}
                  {renderTableHeader('country', 'Event Country')}
                  {renderTableHeader('medication', 'Medication')}
                  {renderTableHeader('adverse_event', 'Adverse Event')}
                  {renderTableHeader('severity', 'Severity')}
                  {renderTableHeader('gender', 'Gender')}
                  {renderTableHeader('age', 'Age')}
                  {renderTableHeader('weight', 'Weight (kg)')}
                  {renderTableHeader('route', 'Route')}
                  {renderTableHeader('start_date', 'Start Date')}
                  {renderTableHeader('end_date', 'End Date')}
                  {renderTableHeader('dosage', 'Dosage')}
                </tr>
              </thead>
              <tbody>
                {sortedEvents.map((event) => (
                  <tr key={`${event.top_safetyreportid}-${event.reaction_reactionmeddrapt}`}>
                    <td>{event.top_safetyreportid}</td>
                    <td>{formatDate(event.top_receivedate)}</td>
                    <td>{event.top_occurcountry || 'Unknown'}</td>
                    <td>{getDrugName(event.drug_medicinalproduct)}</td>
                    <td>{event.reaction_reactionmeddrapt}</td>
                    <td>{getSeverityText(event.top_serious)}</td>
                    <td>{getGenderText(event.patient_patientsex)}</td>
                    <td>
                      {event.patient_patientonsetage != null
                        ? parseInt(event.patient_patientonsetage, 10)
                        : 'Unknown'}
                    </td>
                    <td>{event.patient_patientweight != null ? event.patient_patientweight : 'Unknown'}</td>
                    <td>{formatRoute(event.drug_openfda_route)}</td>
                    <td>{formatDate(event.drug_drugstartdate) || 'Unknown'}</td>
                    <td>{formatDate(event.drug_drugenddate) || 'Unknown'}</td>
                    <td>{getDosage(event.drug_drugstructuredosagenumb, event.drug_drugstructuredosageunit)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <div className="pagination">
            <div className="pagination-info">
              Showing {(currentPage - 1) * pageSize + 1} to {Math.min(currentPage * pageSize, totalEvents)} of {totalEvents} records
              {Object.keys(filters).length > 0 && (
                <button className="reset-filters-btn" onClick={resetAllFilters}>Reset Table Filters</button>
              )}
            </div>

            <div className="pagination-controls">
              <button 
                className="pagination-button" 
                disabled={currentPage === 1}
                onClick={() => onPageChange(currentPage - 1)}
              >
                Previous
              </button>

              {getPageNumbers().map(number => (
                <button
                  key={number}
                  className={`pagination-button ${currentPage === number ? 'active' : ''}`}
                  onClick={() => onPageChange(number)}
                >
                  {number}
                </button>
              ))}

              <button 
                className="pagination-button" 
                disabled={currentPage === totalPages}
                onClick={() => onPageChange(currentPage + 1)}
              >
                Next
              </button>
            </div>
          </div>
        </>
      )}
    </div>
  );
};

export default EventTable;
